        for (let i = 0; i < 7; i++) { const y = 110 + i * 6 + r() * 3; col += `<path d="M${x + 2} ${f(y)}q13 ${f(-3 - r() * 3)} 26 0t26 0t26 0t26 0" fill="none" stroke="#e7a9b4" stroke-width=".9" opacity=".8"/>`; }
