      memo: [["HPV", "=", T("vírus nu, DNA circular", "virus desnudo, ADN circular")], ["L1", ">", T("capsídeo principal", "cápside principal")], ["6 e 11", "=", T("verrugas, baixo risco", "verrugas, bajo riesgo")], ["16 e 18", "=", T("câncer de colo, alto risco", "cáncer de cuello, alto riesgo")]],
