        { q: T("Mulher com verrugas genitais. Quais tipos são mais prováveis?", "Mujer con verrugas genitales. ¿Qué tipos son más probables?"), o: ["6 e 11", "16 e 18", "31 e 33", "45 e 52"], c: 0,
          e: T("6 e 11 são de baixo risco e dão verrugas genitais. 16 e 18 são de alto risco, ligados a displasia e câncer.", "6 y 11 son de bajo riesgo y dan verrugas genitales. 16 y 18 son de alto riesgo, ligados a displasia y cáncer."), d: 0 }
